def max_sum(tri, n):
    """Return the maximum sum of a path from the top to the base of the triangle.

    From a cell the path may move to the cell directly below it or to
    the cell below and one place to the right, visiting exactly one
    cell in each of the first ``n`` rows.
    """
    if n <= 0 or not tri:
        return 0
    n = min(n, len(tri))
    dp = list(tri[n - 1][:n])
    for i in range(n - 2, -1, -1):
        row = tri[i]
        for j in range(min(i + 1, len(row))):
            dp[j] = row[j] + max(dp[j], dp[j + 1])
    return dp[0]
